// SHOC BFS (level1/bfs, IIIT warp-centric method) — standalone self-checking
// OpenCL port for Vortex.
//
// Source:
//   third_benchmark/shoc/src/opencl/level1/bfs/BFS.cpp   (RunTest1)
//   third_benchmark/shoc/src/opencl/level1/bfs/bfs_iiit.cl
//   third_benchmark/shoc/src/opencl/level1/bfs/BFS.cpp:1321 (RunBenchmark)
//
// Graph: SHOC's default input is not random; it is a k-way tree generated by
// Graph::GenerateSimpleKWayGraph (third_benchmark/shoc/src/common/Graph.cpp:286).
// We reproduce that generator exactly (integer arithmetic; SHOC's
// floor((i-1)/degree) is the same as (i-1)/degree for non-negative i).
//
// Reference: SHOC's serial queue BFS, Graph::GetVertexLengths
// (third_benchmark/shoc/src/common/Graph.cpp:348). Both sides compute hop
// counts from vertex 0; unreachable vertices stay UINT_MAX. Comparison is exact
// integer equality (BFS.cpp:100 verify_results).
//
// Not ported from SHOC: OptionParser, ResultDatabase, Event timing, pinned host
// memory, and the --passes loop. The host drives one level-synchronous kernel
// launch per BFS level, exactly as RunTest1 does.

#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <limits.h>
#include <CL/opencl.h>
#include <unistd.h>
#include <string.h>
#include <chrono>
#include <vector>

#define KERNEL_NAME "BFS_kernel_warp"

// Vortex's OpenCL device caps a work-group at 16 work-items
// (NUM_WARPS * NUM_THREADS in VX_config.toml).
#define LWS 16
// The kernel partitions one vertex's edges across W_SZ consecutive work-items.
// The global size must be a multiple of W_SZ, otherwise a partially launched
// 32-group would leave some edges unvisited in the last vertex chunk.
#define W_SZ 32
#define CHUNK_SZ 32

#define BFS_UNREACHED 0xffffffffu

#define CL_CHECK(_expr)                                                \
   do {                                                                \
     cl_int _err = _expr;                                              \
     if (_err == CL_SUCCESS)                                           \
       break;                                                          \
     printf("OpenCL Error: '%s' returned %d!\n", #_expr, (int)_err);   \
     cleanup();                                                        \
     exit(-1);                                                         \
   } while (0)

#define CL_CHECK2(_expr)                                               \
   ({                                                                  \
     cl_int _err = CL_INVALID_VALUE;                                   \
     decltype(_expr) _ret = _expr;                                     \
     if (_err != CL_SUCCESS) {                                         \
       printf("OpenCL Error: '%s' returned %d!\n", #_expr, (int)_err); \
       cleanup();                                                      \
       exit(-1);                                                       \
     }                                                                 \
     _ret;                                                             \
   })

static int read_kernel_file(const char* filename, uint8_t** data, size_t* size) {
  if (nullptr == filename || nullptr == data || 0 == size)
    return -1;

  FILE* fp = fopen(filename, "r");
  if (NULL == fp) {
    fprintf(stderr, "Failed to load kernel.");
    return -1;
  }

  fseek(fp, 0, SEEK_END);
  long fsize = ftell(fp);
  rewind(fp);

  *data = (uint8_t*)malloc(fsize);
  *size = fread(*data, 1, fsize, fp);

  fclose(fp);

  return 0;
}

// SHOC Graph::GenerateSimpleKWayGraph (Graph.cpp:286).
static void build_kway_graph(unsigned int n, unsigned int degree,
                             std::vector<unsigned int>& offsets,
                             std::vector<unsigned int>& edges) {
  offsets.assign(n + 1, 0);
  edges.clear();
  edges.reserve((size_t)n * (degree + 1));

  unsigned int offset = 0;
  for (unsigned int i = 0; i < n; ++i) {
    offsets[i] = offset;
    for (unsigned int j = 0; j < degree; ++j) {
      unsigned int child = i * degree + (j + 1);
      if (child < n) {
        edges.push_back(child);
        ++offset;
      }
    }
    if (i != 0) {
      edges.push_back((i - 1) / degree);
      ++offset;
    }
  }
  offsets[n] = offset;
}

// SHOC Graph::GetVertexLengths (Graph.cpp:348): serial queue BFS.
static void bfs_cpu(const std::vector<unsigned int>& offsets,
                    const std::vector<unsigned int>& edges,
                    unsigned int n, unsigned int source,
                    std::vector<unsigned int>& cost) {
  cost.assign(n, BFS_UNREACHED);
  cost[source] = 0;

  std::vector<unsigned int> queue;
  queue.reserve(n);
  queue.push_back(source);

  for (size_t head = 0; head < queue.size(); ++head) {
    unsigned int v = queue[head];
    for (unsigned int e = offsets[v]; e < offsets[v + 1]; ++e) {
      unsigned int u = edges[e];
      if (cost[u] == BFS_UNREACHED) {
        cost[u] = cost[v] + 1;
        queue.push_back(u);
      }
    }
  }
}

cl_device_id device_id = NULL;
cl_context context = NULL;
cl_command_queue commandQueue = NULL;
cl_program program = NULL;
cl_kernel kernel = NULL;
cl_mem levels_memobj = NULL;
cl_mem offsets_memobj = NULL;
cl_mem edges_memobj = NULL;
cl_mem flag_memobj = NULL;
uint8_t* kernel_bin = NULL;

static void cleanup() {
  if (commandQueue) clReleaseCommandQueue(commandQueue);
  if (kernel) clReleaseKernel(kernel);
  if (program) clReleaseProgram(program);
  if (levels_memobj) clReleaseMemObject(levels_memobj);
  if (offsets_memobj) clReleaseMemObject(offsets_memobj);
  if (edges_memobj) clReleaseMemObject(edges_memobj);
  if (flag_memobj) clReleaseMemObject(flag_memobj);
  if (context) clReleaseContext(context);
  if (device_id) clReleaseDevice(device_id);

  if (kernel_bin) free(kernel_bin);
}

int nvertices = 256;
int degree = 2;

static void show_usage() {
  printf("Usage: [-n vertices] [-d degree] [-h: help]\n");
}

static void parse_args(int argc, char **argv) {
  int c;
  while ((c = getopt(argc, argv, "n:d:h")) != -1) {
    switch (c) {
    case 'n':
      nvertices = atoi(optarg);
      break;
    case 'd':
      degree = atoi(optarg);
      break;
    case 'h':
      show_usage();
      exit(0);
      break;
    default:
      show_usage();
      exit(-1);
    }
  }

  printf("BFS vertices=%d degree=%d\n", nvertices, degree);
}

int main(int argc, char **argv) {
  parse_args(argc, argv);

  if (nvertices < 2) {
    printf("Error: number of vertices must be at least 2\n");
    return -1;
  }
  if (degree < 1) {
    printf("Error: degree must be at least 1\n");
    return -1;
  }

  const unsigned int n = (unsigned int)nvertices;
  const unsigned int source = 0;

  std::vector<unsigned int> offsets;
  std::vector<unsigned int> edges;
  build_kway_graph(n, (unsigned int)degree, offsets, edges);

  printf("Vertices: %u, adjacency entries: %zu\n", n, edges.size());

  std::vector<unsigned int> h_levels(n, BFS_UNREACHED);
  h_levels[source] = 0;

  cl_platform_id platform_id;
  CL_CHECK(clGetPlatformIDs(1, &platform_id, NULL));
  CL_CHECK(clGetDeviceIDs(platform_id, CL_DEVICE_TYPE_DEFAULT, 1, &device_id, NULL));
  context = CL_CHECK2(clCreateContext(NULL, 1, &device_id, NULL, NULL, &_err));

  printf("Create program from kernel source\n");
  size_t kernel_size = 0;
  if (0 != read_kernel_file("kernel.cl", &kernel_bin, &kernel_size))
    return -1;
  program = CL_CHECK2(clCreateProgramWithSource(
    context, 1, (const char**)&kernel_bin, &kernel_size, &_err));

  CL_CHECK(clBuildProgram(program, 1, &device_id, NULL, NULL, NULL));

  kernel = CL_CHECK2(clCreateKernel(program, KERNEL_NAME, &_err));

  const size_t offsets_nbytes = (size_t)(n + 1) * sizeof(unsigned int);
  const size_t edges_nbytes = edges.size() * sizeof(unsigned int);
  const size_t levels_nbytes = (size_t)n * sizeof(unsigned int);
  const size_t flag_nbytes = sizeof(int);

  levels_memobj = CL_CHECK2(clCreateBuffer(context, CL_MEM_READ_WRITE,
                                           levels_nbytes, NULL, &_err));
  offsets_memobj = CL_CHECK2(clCreateBuffer(context, CL_MEM_READ_ONLY,
                                            offsets_nbytes, NULL, &_err));
  edges_memobj = CL_CHECK2(clCreateBuffer(context, CL_MEM_READ_ONLY,
                                          edges_nbytes, NULL, &_err));
  flag_memobj = CL_CHECK2(clCreateBuffer(context, CL_MEM_READ_WRITE,
                                         flag_nbytes, NULL, &_err));

  int W_SZ_arg = W_SZ;
  int CHUNK_SZ_arg = CHUNK_SZ;
  CL_CHECK(clSetKernelArg(kernel, 0, sizeof(cl_mem), (void *)&levels_memobj));
  CL_CHECK(clSetKernelArg(kernel, 1, sizeof(cl_mem), (void *)&offsets_memobj));
  CL_CHECK(clSetKernelArg(kernel, 2, sizeof(cl_mem), (void *)&edges_memobj));
  CL_CHECK(clSetKernelArg(kernel, 3, sizeof(int), (void *)&W_SZ_arg));
  CL_CHECK(clSetKernelArg(kernel, 4, sizeof(int), (void *)&CHUNK_SZ_arg));
  CL_CHECK(clSetKernelArg(kernel, 5, sizeof(unsigned int), (void *)&n));
  CL_CHECK(clSetKernelArg(kernel, 7, sizeof(cl_mem), (void *)&flag_memobj));

  commandQueue = CL_CHECK2(clCreateCommandQueue(context, device_id, 0, &_err));

  printf("Upload source buffers\n");
  CL_CHECK(clEnqueueWriteBuffer(commandQueue, offsets_memobj, CL_TRUE, 0,
                                offsets_nbytes, offsets.data(), 0, NULL, NULL));
  CL_CHECK(clEnqueueWriteBuffer(commandQueue, edges_memobj, CL_TRUE, 0,
                                edges_nbytes, edges.data(), 0, NULL, NULL));

  const size_t local_work_size = LWS;
  const size_t global_work_size =
      ((n + W_SZ - 1) / W_SZ) * W_SZ;  // multiple of W_SZ (and of LWS)

  printf("Execute the kernel\n");
  auto time_start = std::chrono::high_resolution_clock::now();

  // Upload the frontier/levels array once; the kernel updates it in place
  // across levels, exactly like SHOC RunTest1 (BFS.cpp:293).
  CL_CHECK(clEnqueueWriteBuffer(commandQueue, levels_memobj, CL_TRUE, 0,
                                levels_nbytes, h_levels.data(), 0, NULL, NULL));

  int flag = 1;
  int iters = 0;
  while (flag) {
    flag = 0;
    CL_CHECK(clEnqueueWriteBuffer(commandQueue, flag_memobj, CL_TRUE, 0,
                                  flag_nbytes, &flag, 0, NULL, NULL));
    CL_CHECK(clSetKernelArg(kernel, 6, sizeof(int), (void *)&iters));
    CL_CHECK(clEnqueueNDRangeKernel(commandQueue, kernel, 1, NULL,
                                    &global_work_size, &local_work_size,
                                    0, NULL, NULL));
    CL_CHECK(clFinish(commandQueue));
    CL_CHECK(clEnqueueReadBuffer(commandQueue, flag_memobj, CL_TRUE, 0,
                                 flag_nbytes, &flag, 0, NULL, NULL));
    ++iters;

    // A k-way tree has depth < n; a longer loop means the kernel never sets
    // the done flag (or the flag handshake is broken).
    if (iters > nvertices) {
      printf("Error: BFS did not converge after %d levels\n", iters);
      cleanup();
      return -1;
    }
  }

  CL_CHECK(clEnqueueReadBuffer(commandQueue, levels_memobj, CL_TRUE, 0,
                               levels_nbytes, h_levels.data(), 0, NULL, NULL));
  auto time_end = std::chrono::high_resolution_clock::now();
  double elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(time_end - time_start).count();
  printf("BFS levels: %d, elapsed time: %lg ms\n", iters, elapsed);

  printf("Verify result\n");
  std::vector<unsigned int> h_cost_ref;
  bfs_cpu(offsets, edges, n, source, h_cost_ref);

  int errors = 0;
  for (unsigned int i = 0; i < n; ++i) {
    if (h_levels[i] != h_cost_ref[i]) {
      if (errors < 100) {
        printf("*** error: [%u] expected=%u, actual=%u\n",
               i, h_cost_ref[i], h_levels[i]);
      }
      ++errors;
    }
  }

  if (0 == errors) {
    printf("PASSED!\n");
  } else {
    printf("FAILED! - %d errors\n", errors);
  }

  cleanup();

  return errors;
}
